package com.oms.supplychain.service.wms;

import com.oms.supplychain.service.warehouse.impl.PurchaseWorkspaceService;
import org.springframework.stereotype.Service;
import org.springframework.context.annotation.Lazy;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Warehouse facts are retained separately from accepted receipts and stock. */
@Service public class PurchaseReceiptDifferences {
    @Resource WmsStore db;
    @Resource @Lazy PurchaseWorkspaceService purchase;
    public void retain(String c,Map<String,Object> task,WmsProtocol.Receipt receipt,long log,String kind,String reason,long difference){
        long expected=db.jdbc.queryForObject("SELECT COALESCE(SUM(number_expected),0) FROM wms_tickets_goods WHERE company_code=? AND sn=?",Long.class,c,task.get("ticket_sn"));
        long total=receipt.lines.stream().mapToLong(l->(long)l.good+l.bad).sum();String payload=db.encode(receipt);
        db.jdbc.update("INSERT IGNORE INTO purchase_receipt_difference(company_code,task_id,ticket_id,ticket_sn,message_id,receipt_hash,difference_kind,expected_quantity,reported_quantity,difference_quantity,receipt_json,source_log_id,reason) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",c,task.get("id"),task.get("ticket_id"),task.get("ticket_sn"),receipt.messageId,QimenProtocol.hash("SHA-256",payload),kind,expected,total,difference,payload,log,reason);
    }
    public void accepted(String c,Map<String,Object> task,WmsProtocol.Receipt receipt,long log){
        db.jdbc.update("UPDATE purchase_receipt_difference SET state='CORRECTED',decision='CLOSE',resolution_reason='仓库后续更正回传已按原消息接收',actor='系统',control_version=control_version+1 WHERE company_code=? AND task_id=? AND message_id=? AND difference_kind IN ('OVER','WRONG_SKU','LATE') AND state IN ('OPEN','WAITING')",c,task.get("id"),receipt.messageId);
        long bad=receipt.lines.stream().mapToLong(l->l.bad).sum();if(bad>0)retain(c,task,receipt,log,"QUALITY","仓库次品已按真实质量记录；入账结果及供应商处理需分别核对",bad);
        if(receipt.complete||"COMPLETE".equals(db.one("SELECT receipt_state FROM wms_inbound_task WHERE company_code=? AND id=?",c,task.get("id")).get("receipt_state"))){long shortQty=db.jdbc.queryForObject("SELECT COALESCE(SUM(GREATEST(number_expected-number_actually-cancelled_quantity,0)),0) FROM wms_tickets_goods WHERE company_code=? AND sn=?",Long.class,c,task.get("ticket_sn"));if(shortQty>0){db.jdbc.update("UPDATE purchase_receipt_difference SET state='CORRECTED',decision='CLOSE',resolution_reason='后续最终回传已更新短收数量，请核对最新差异',actor='系统',control_version=control_version+1 WHERE company_code=? AND task_id=? AND difference_kind='SHORT' AND receipt_hash<>? AND state IN('OPEN','WAITING')",c,task.get("id"),QimenProtocol.hash("SHA-256",db.encode(receipt)));retain(c,task,receipt,log,"SHORT","仓库最终回传存在短收；本批实收入账后可补建到货或处理剩余采购",shortQty);}else db.jdbc.update("UPDATE purchase_receipt_difference SET state='CORRECTED',decision='CLOSE',resolution_reason='后续真实回传已收齐原本批计划',actor='系统',control_version=control_version+1 WHERE company_code=? AND task_id=? AND difference_kind='SHORT' AND state IN ('OPEN','WAITING')",c,task.get("id"));}
    }
    public Map<String,Object> detail(String c,long key){Map<String,Object> r=db.one("SELECT * FROM purchase_receipt_difference WHERE company_code=? AND id=?",c,key);try{WmsProtocol.Receipt fact=db.json.readValue(text(r.remove("receipt_json")),WmsProtocol.Receipt.class);List<Map<String,Object>> lines=new ArrayList<>();for(WmsProtocol.Line l:fact.lines)lines.add(map("sku",l.sku,"batch",l.batch,"good",l.good,"bad",l.bad));r.put("lines",lines);r.put("final_receipt",fact.complete);}catch(Exception e){throw new IllegalArgumentException("原仓库差异快照无法读取");}r.remove("receipt_hash");ReturnQueryWarehouse.formatTimes(r);return r;}
    public List<Map<String,Object>> list(String c,String kind,long key){require(Arrays.asList("purchase","receipt","ticket").contains(kind),"差异查询范围无效");String col="purchase".equals(kind)?"p.id":"receipt".equals(kind)?"n.id":"t.id";List<Map<String,Object>> rows=db.jdbc.queryForList("SELECT d.id,d.ticket_sn,d.message_id,d.difference_kind,d.expected_quantity,d.reported_quantity,d.difference_quantity,d.state,d.reason,d.resolution_reason,d.actor,d.resolution_receipt_id,d.control_version,d.create_time,d.update_time FROM purchase_receipt_difference d JOIN wms_tickets t ON t.company_code=d.company_code AND t.id=d.ticket_id JOIN no_tickets n ON n.company_key=d.company_code AND n.no_sn=t.relation_sn JOIN po_info p ON p.company_key=d.company_code AND p.po_sn=n.po_sn WHERE d.company_code=? AND "+col+"=? ORDER BY d.id DESC LIMIT 201",c,key);require(rows.size()<=200,"差异记录超过200项，请按入库单查询");for(Map<String,Object> r:rows)ReturnQueryWarehouse.formatTimes(r);return rows;}
    public Map<String,Object> decide(String c,long key,Map<String,Object> body,String actor){String decision=required(body,"decision",24),reason=required(body,"reason",1000);require(Arrays.asList("WAIT_CORRECTION","REJECT","KEEP_BAD","REARRANGE").contains(decision),"差异处理动作无效");return db.tx().execute(tx->{
        Map<String,Object> locator=db.one("SELECT ticket_id FROM purchase_receipt_difference WHERE company_code=? AND id=?",c,key);Map<String,Object> ticket=purchase.lockWmsTicket(c,id(locator.get("ticket_id")));Map<String,Object> d=db.one("SELECT * FROM purchase_receipt_difference WHERE company_code=? AND id=? FOR UPDATE",c,key);
        require(id(d.get("control_version"))==id(body.get("control_version")),"差异记录已变化，请刷新后重新核对");require(Arrays.asList("OPEN","WAITING").contains(text(d.get("state"))),"差异已处理，不可重复执行");String kind=text(d.get("difference_kind"));Long nextReceipt=null;String state="RESOLVED";
        if("REARRANGE".equals(decision)){
            require("SHORT".equals(kind),"只有最终短收允许按差额补建到货");require("COMPLETE".equals(db.one("SELECT receipt_state FROM wms_inbound_task WHERE company_code=? AND id=?",c,d.get("task_id")).get("receipt_state")),"仓库尚未最终确认收货");require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_receipt_line WHERE company_code=? AND task_id=? AND posted<>1",Long.class,c,d.get("task_id"))==0,"本批仍有未入账实收，请先完成入账");
            List<Map<String,Object>> shortages=db.jdbc.queryForList("SELECT l.id lineId,GREATEST(g.number_expected-g.number_actually-g.cancelled_quantity,0) quantity FROM wms_tickets_goods g JOIN purchase_line l ON l.company_code=g.company_code AND l.po_sn=? AND l.sku_sn=g.sku_sn WHERE g.company_code=? AND g.sn=? AND g.number_expected>g.number_actually+g.cancelled_quantity",ticket.get("originalSn"),c,d.get("ticket_sn"));require(!shortages.isEmpty(),"当前已无可补建的短收数量");long po=db.jdbc.queryForObject("SELECT id FROM po_info WHERE company_key=? AND po_sn=?",Long.class,c,ticket.get("originalSn"));nextReceipt=purchase.createReceipt(c,po,map("lines",shortages,"remarks",("短收差异补建 #"+key+"；"+reason).substring(0,Math.min(255,("短收差异补建 #"+key+"；"+reason).length()))),actor);
        }else if("KEEP_BAD".equals(decision)){
            require("QUALITY".equals(kind),"只有次品差异可确认留库处理");long postedBad=db.jdbc.queryForObject("SELECT COALESCE(SUM(l.bad_qty),0) FROM wms_receipt_line l JOIN wms_receipt_event e ON e.company_code=l.company_code AND e.id=l.event_id WHERE l.company_code=? AND l.task_id=? AND e.message_id=? AND l.posted=1",Long.class,c,d.get("task_id"),d.get("message_id"));require(postedBad>=id(d.get("difference_quantity")),"本次次品尚未全部入账，请先核对入账结果");
        }else if("REJECT".equals(decision)){require(Arrays.asList("OVER","WRONG_SKU","LATE").contains(kind),"已确认的短收或次品不能按未接收回传拒收");state="REJECTED";}else state="WAITING";
        db.jdbc.update("UPDATE purchase_receipt_difference SET state=?,decision=?,resolution_reason=?,actor=?,resolution_receipt_id=?,control_version=control_version+1 WHERE company_code=? AND id=?",state,decision,reason,actor,nextReceipt,c,key);purchase.recordWmsEvent(c,text(d.get("ticket_sn")),"收货差异处理",actor+"："+decision+"；"+reason);return map("id",key,"state",state,"receipt_id",nextReceipt);
    });}
}
